(function(){document.addEventListener('DOMContentLoaded',function(){try{var id=localStorage.getItem('current_theme_id_for_distribute'),theme=JSON.parse(localStorage.getItem('kiosk_themes')||'[]').find(function(t){return t.id===id;});if(!theme||!theme.adSlot)return;var line=document.createElement('div');line.className='px-6 pt-4 text-center text-sm text-gray-500';line.textContent='投放渠道：'+theme.adSlot.productLine+'　展示位置：'+theme.adSlot.name+'　规格V'+theme.adSlot.version;document.querySelector('header').after(line);}catch(error){}});})();
